insert into candidate (id, agency_id, name, age, based_in, profession, faith, about) values
  ('d0663f5a-75c3-576a-9c7c-7a5d75b881bd', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Stephanie C', '35', 'New York', 'Operations @ VC Firm', 'Christian', 'Stephanie is smart, beautiful, and confident, with a natural poise and outgoing energy. She recently moved back to New York for her role at a VC firm. She knows what she''s looking for and is clear that she wants a family.'),
  ('12e795b7-274b-5e26-bb3b-6ce22cb807aa', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Selin U', '30', 'New York', 'Business Program Manager', 'Christian', 'Raised in Northern Virginia with deep Turkish family roots, Selin leads strategic technology initiatives remotely and graduated at the top of her class. Outside work she balances tennis, Sunday baking, yoga, and photography with a love of classic literature and travel. Friends call her thoughtful, adventurous, and graceful. Height 5''7". Looking for someone kind, ambitious, and ready to build a real connection.'),
  ('4b7b7d51-15e7-561e-9be7-e75c157bc690', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Katya D', '30', 'Miami', 'Profile Miami Co-Founder & Development Sales', 'Christian', 'Katya grew up in LA and moved to New York (her father has a senior role at a hedgefund) and she is in NYC semi often for work. Open to moving back to the city especially because her family is so close. She has an infectious happy energy and is a talented person - she plays piano, sings and'),
  ('7ea0eb8b-117f-5dee-a5b1-df32e29f1633', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Sabrina S', '33', 'New York', 'Founder, luxury travel consultancy (superyacht charters)', '', 'Sabrina grew up immersed in the yachting world as the daughter of a well-known yachting journalist, and has built her own boutique consultancy managing global travel for private charter clients. She''s known for creating unforgettable experiences. Discerning, resourceful, and composed, she brings taste and intuition to everything she does.'),
  ('3f41f84a-8bc8-533a-b9e7-8818be3f3cf6', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Morgan D', '29', 'New York City', 'Civil Engineer', 'Catholic', 'Kind, smart and just a solid person overall. She has her own career and life but is commitment oriented and ready for family. Referred by a very close friend and waiting to interview her upon request.'),
  ('54fabef1-8614-5d50-9454-93783338d937', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Sofia S', '24', 'New York', 'DJ & Model', 'Christian', 'Sofia is hard working, from a nice family and knows how to have fun. Only recently single. Maybe not the right type but has a sizable network of friends her age.'),
  ('b2bb91f3-8fc2-50c4-a4e1-baa837d525ef', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Madison', '31', 'New York', 'Attorney', '', 'Madison is an attorney and native New Yorker. She loves travel and adventure and is an avid NYC sports fan. Family is central to her life and she''s especially close with her older brothers, nieces, and nephews. She loves a dance floor. Height 5''6".'),
  ('5ab5b034-8486-5917-8851-528b5e0a95a4', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Solenne "Twiga"', '30', 'Miami', 'Material Good', 'Catholic', 'Former successful natural red head model. (Her look is not for everyone but she is a very unique beauty.) Innate sense of style. Senior at Material Good. Equestrian.'),
  ('00991521-7dd9-5ec4-bde1-c8dd58dbd7c7', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Bailey T', '28', 'Los Angeles', 'Photographer', 'Christian', 'Frequently in NYC for work but based in LA. Would move for the right person. Bailey is a natural beauty and real talent. Sober'),
  ('02607c36-113b-51a7-9a8d-1a696af86388', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Erica', '33', 'Los Angeles', 'Tech founder & angel investor', 'Christian', 'A former Miss New York turned tech founder, strategist, and angel investor, Erica pairs a powerful résumé with an equally powerful heart. Originally from the Midwest, she brings grace, warmth, and depth to everything she touches. She mentors youth, hosts a wellness podcast, and is an accomplished tri-athlete — riding horses, curating art, or deep in a new book, she lives with intention. Height 5''6". She''s ready for a partner who values strength, softness, and a shared vision for a beautiful life.'),
  ('19ecdc70-5347-5d15-b961-df39e7e0376b', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Ashleigh S', '37', 'Miami', 'Dermatologist', 'Jewish - not religious', 'Ashleigh is very family oriented, has accomplished a lot professionally and would be willing to relocate for the right person. She is tall (5''10") curvy and beautiful,'),
  ('6245e4f4-b012-5fab-a2c2-7ec1c3f7645f', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Sandra W', '33', 'New York City', 'Director, screenwriter & photographer', '', 'Sandra is a Danish director, screenwriter, and photographer based in New York. Her debut feature Lowland Kids, produced by Darren Aronofsky''s Protozoa Pictures, premiered at CPH:DOX, with a theatrical release coming in 2026. Her documentary A New Wave ran as a New York Times Op-Doc in 2024.'),
  ('c689e68b-beed-5320-bfe8-98afe53113d4', '895283e1-7886-5868-89d0-b31a8b0dd695', 'Johanna D', '38', 'Miami', 'Head of retail Ventures @ Starwood and co-owner of furniture, home and lifestyle brand', 'Jewish', 'You wouldn''t expect someone as effortlessly chic as Johanna to also be so approachable and kind. She is a very passionate woman. A few years older than ideal so will hold for now.
