insert into roster_item (id, roster_id, candidate_id, city_id, status, blurb, position) values
  ('e64a9d01-23b1-5a2d-9e64-6784a9f22fca', '2697a1d1-335a-58a4-8d89-613b3c2dee44', 'd0663f5a-75c3-576a-9c7c-7a5d75b881bd', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Smart, beautiful, just moved back to NYC.', 0),
  ('d92684ee-46a3-5a47-b36a-0d4e6a2dd947', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '12e795b7-274b-5e26-bb3b-6ce22cb807aa', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Sophisticated and playful, with depth — thoughtful, adventurous and graceful.', 1),
  ('cd0e363c-642c-5f3e-8945-5e3fd50117dd', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '4b7b7d51-15e7-561e-9be7-e75c157bc690', 'bbe7afe2-b92e-55ad-9958-c375f5b09ea9', 'hold', 'Talented, warm, smart, down to earth, petite, curvy, hilarious.', 2),
  ('bedd3a05-df95-5ae5-96a2-39792d3e1585', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '7ea0eb8b-117f-5dee-a5b1-df32e29f1633', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Worldly and resourceful, with an insider''s eye for the extraordinary.', 3),
  ('1e94c2ad-8491-5587-a81b-41adb748bb07', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '3f41f84a-8bc8-533a-b9e7-8818be3f3cf6', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Adorable, successful and ready for true partnership.', 4),
  ('63280d3b-538a-5dd5-bfc9-d8a7f61e128a', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '54fabef1-8614-5d50-9454-93783338d937', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Sweet, beautiful, friendly and cool.', 5),
  ('b2fae496-460d-569d-8d0b-1b9ae834a44f', '2697a1d1-335a-58a4-8d89-613b3c2dee44', 'b2bb91f3-8fc2-50c4-a4e1-baa837d525ef', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'maybe', 'Kind, smart, and outgoing — a native New Yorker attorney with a big heart for family and friends.', 6),
  ('9c0f1067-d228-5fde-95ea-614c77da2a3d', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '5ab5b034-8486-5917-8851-528b5e0a95a4', 'bbe7afe2-b92e-55ad-9958-c375f5b09ea9', 'hold', 'Smart, unique, sophisticated French girl in Miami.', 7),
  ('c684b2f1-5a55-5cf4-b529-b6a03cea2da6', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '00991521-7dd9-5ec4-bde1-c8dd58dbd7c7', '1fc853cc-c704-569a-87d1-df3e99724bf3', 'hold', 'down to earth, sweet natured professional photographer. Frequently in nyc', 8),
  ('ca4acbed-62a3-5bd6-bab6-3bbcf6b1c4f9', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '02607c36-113b-51a7-9a8d-1a696af86388', '1fc853cc-c704-569a-87d1-df3e99724bf3', 'hold', 'Feminine, sophisticated, and driven — a former Miss New York turned tech founder with real depth of character.', 9),
  ('7fd72cc1-a90b-583c-8c60-b0d999af21c5', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '19ecdc70-5347-5d15-b961-df39e7e0376b', 'bbe7afe2-b92e-55ad-9958-c375f5b09ea9', 'maybe', 'Unicorn doctor', 10),
  ('e5960232-7f11-5d83-8735-9aac1cb70fb6', '2697a1d1-335a-58a4-8d89-613b3c2dee44', '6245e4f4-b012-5fab-a2c2-7ec1c3f7645f', '84aefaf8-9715-55cd-85cb-33bfc8c9d496', 'passed', 'A Danish filmmaker with a bold, cinematic eye.', 11),
  ('d30c3413-1e71-559e-b887-297b4f829492', '2697a1d1-335a-58a4-8d89-613b3c2dee44', 'c689e68b-beed-5320-bfe8-98afe53113d4', 'bbe7afe2-b92e-55ad-9958-c375f5b09ea9', 'hold', 'True badass: smart, beautiful, petite, successful.', 12),
